//! The columns of platform tables that the corpus pins, derived from the corpus so that
//! `al_builtins::platform::PINNED_COLUMNS` cannot drift from it.
//!
//! A column is pinned when a file of the corpus's test apps names it (`Rec."Login Type"`, a
//! `SetRange` or `CalcFields` on it: the checker's `Res::Field` resolutions), or when
//! `al_builtins::platform::PINNED_ELSEWHERE` lists it with the corpus test that reads it another
//! way (by number through a `RecordRef`, through Microsoft's code, from a declaration). The
//! generated file is `crates/al-builtins/src/pinned_columns.rs`; the release test
//! `pinned_columns_are_current` (tests/corpus_resolve_deps.rs) checks it, and `UPDATE_GOLDEN=1`
//! rewrites it.

use al_sema::Workspace;
use al_sema::check::{CheckResult, Res};
use std::collections::{BTreeMap, BTreeSet};

/// For each platform table of `tables`, the field ids (below the system fields) that the
/// workspace apps' files name.
pub fn named_columns(ws: &Workspace, checked: &CheckResult, tables: &[u32]) -> BTreeMap<u32, BTreeSet<u32>> {
    let mut out: BTreeMap<u32, BTreeSet<u32>> = tables.iter().map(|t| (*t, BTreeSet::new())).collect();
    for (key, res) in checked.resolutions.iter() {
        let (file, _, _) = &key;
        let Res::Field { table, id } = res.inner() else {
            continue;
        };
        if ws.kinds[ws.files[*file].app] != al_sema::AppKind::Workspace || !ws.platform_table(*table) {
            continue;
        }
        let Some(tid) = ws.objects[*table].id else { continue };
        if *id >= al_builtins::platform::SYSTEM_OBJECT_BASE {
            continue;
        }
        if let Some(cols) = out.get_mut(&tid) {
            cols.insert(*id);
        }
    }
    out
}

/// The pinned columns: the named ones and `PINNED_ELSEWHERE`, per table of `PINNED_TABLES`.
pub fn pinned_columns(ws: &Workspace, checked: &CheckResult) -> BTreeMap<u32, BTreeSet<u32>> {
    let mut out = named_columns(ws, checked, al_builtins::platform::PINNED_TABLES);
    let members = al_sema::members::build(ws);
    for (t, field, _) in al_builtins::platform::PINNED_ELSEWHERE {
        let id = field.parse::<u32>().ok().or_else(|| {
            let oi = (0..ws.objects.len()).find(|&i| ws.platform_table(i) && ws.objects[i].id == Some(*t))?;
            members[oi].field(field).map(|f| f.id)
        });
        let id = id.unwrap_or_else(|| panic!("PINNED_ELSEWHERE: table {t} has no field `{field}`"));
        out.entry(*t).or_default().insert(id);
    }
    out
}

/// The generated Rust source of `crates/al-builtins/src/pinned_columns.rs`. It does not name the corpus commit: the
/// file then changes only when a pinned column changes, not with every corpus bump.
pub fn to_rust(cols: &BTreeMap<u32, BTreeSet<u32>>) -> String {
    let mut s = String::new();
    s.push_str("// Generated by `al_test_cli::platform_columns` from the corpus.");
    s.push_str("\n// Do not edit: UPDATE_GOLDEN=1 cargo test --release -p al-test-cli --test corpus_resolve_deps -- --ignored\n\n");
    s.push_str("/// The columns of a platform table that the corpus pins, by table id (`platform::PINNED_COLUMNS`).\n");
    s.push_str("#[rustfmt::skip]\n");
    s.push_str("pub const GENERATED: &[(u32, &[u32])] = &[\n");
    for (t, c) in cols {
        let list = c.iter().map(u32::to_string).collect::<Vec<_>>().join(", ");
        s.push_str(&format!("    ({t}, &[{list}]),\n"));
    }
    s.push_str("];\n");
    s
}
